fn demand_driven_python_stream(
    locals: TaskLocals,
    generator: Bound<'_, PyAny>,
) -> PyResult<PyItemStream> {
    let anext = generator.getattr("__anext__")?.unbind();
    let stream = futures::stream::unfold((anext, locals), |(anext, locals)| async move {
        let next = Python::with_gil(|py| {
            pyo3_async_runtimes::into_future_with_locals(&locals, anext.bind(py).call0()?)
        });
        let item = match next {
            Ok(next) => next.await,
            Err(error) => Err(error),
        };
        if item.as_ref().is_err_and(|error| {
            Python::with_gil(|py| {
                error.is_instance_of::<pyo3::exceptions::PyStopAsyncIteration>(py)
            })
        }) {
            None
        } else {
            Some((item, (anext, locals)))
        }
    });
    Ok(Box::pin(stream))
}

/// The span is private — engine code reaches it via [`Context::current_span`]
/// (the auto-span proxy) or [`Context::start_span`] (a child span). The
/// facade in `dynamo.common.backend.telemetry` is a one-line wrapper around
/// those methods.
#[derive(Clone)]
#[pyclass]
pub struct Context {
    inner: Arc<dyn AsyncEngineContext>,
    trace_context: Option<DistributedTraceContext>,
    first_token: Option<FirstTokenNotifier>,
    metadata: Arc<Mutex<BTreeMap<String, String>>>,
    /// Captured `engine.generate` span. `None` for Python-instantiated test
    /// contexts (where no parent span was plumbed in) — `current_span` /
    /// `start_span` return a no-op `SpanProxy` in that case.
    span: Option<tracing::Span>,
}

#[derive(Clone)]
#[pyclass]
pub struct ContextMetadata {
    inner: Arc<Mutex<BTreeMap<String, String>>>,
}

impl ContextMetadata {
    fn lock_map(&self) -> MutexGuard<'_, BTreeMap<String, String>> {
        self.inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

